import React from "react";
import Product from "./Product";
import CustomNav from "../CustomsNav";
import { Row, Col } from "reactstrap";
import { useProducts } from "./useProduct";

const Home = () => {
  const { categories, products } = useProducts();

  return (
    <div>
      <CustomNav />
      <div className="home">
        <h2 style={{ textAlign: "center" }}>Enjoy our sales!</h2>
        
        {/* Check if categories exist */}
        {categories.length ? (
          categories.map((category) => {
            // Filter products by category ID
            const filteredProducts = products.filter(
              (product) =>
                product?.attributes?.category?.id === category.id
            );

            // Only render category if there are products
            return filteredProducts.length > 0 ? (
              <div key={category.id} className="category-section">
                <h3 className="category-title">{category?.attributes?.name || "No Name"}</h3>
                
                <Row>
                  {/* Display products for the category */}
                  {filteredProducts.map((product) => (
                    <Col sm="12" md="4" key={product.id}>
                      <Product product={product} />
                    </Col>
                  ))}
                </Row>
              </div>
            ) : null;
          })
        ) : (
          <p>Loading categories...</p>
        )}
      </div>
    </div>
  );
};

export default Home;
